select jsonb_pretty(jsonb_build_object('database',current_database(),'server_version',current_setting('server_version'),'migration_history_exists',to_regclass('supabase_migrations.schema_migrations') is not null,'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default) order by table_name,ordinal_position) from information_schema.columns where table_schema='public' and table_name in ('riders','users','vendors','orders','vendor_orders','rider_assignments','notifications')),'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) order by c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('riders','users','vendors','orders','vendor_orders','rider_assignments','notifications')),'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) order by tablename,indexname) from pg_indexes where schemaname='public' and tablename in ('riders','users','vendors','orders','vendor_orders','rider_assignments','notifications')),'riders',(select jsonb_build_object('rows',count(*),'null_userid',count(*) filter(where userid is null),'available_true',count(*) filter(where is_available is true),'available_null',count(*) filter(where is_available is null),'legacy_available_true',count(*) filter(where isavailable is true),'legacy_available_null',count(*) filter(where isavailable is null),'availability_disagreements',count(*) filter(where is_available is distinct from isavailable),'identity_digest',md5(coalesce(string_agg(id::text||':'||coalesce(userid::text,'NULL'),',' order by id),''))) from public.riders),'duplicate_rider_userids',(select count(*) from (select userid from public.riders where userid is not null group by userid having count(*)>1) d))) as fr21_preflight;

select jsonb_pretty(jsonb_build_object('rls',(select jsonb_agg(jsonb_build_object('table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('riders','users','vendors','orders','vendor_orders','rider_assignments','notifications')),'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname='public' and tablename in ('riders','users','vendors','orders','vendor_orders','rider_assignments','notifications')),'grants',(select jsonb_agg(jsonb_build_object('table',table_name,'role',grantee,'privilege',privilege_type) order by table_name,grantee,privilege_type) from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','PUBLIC') and table_name in ('riders','users','vendors','orders','vendor_orders','rider_assignments','notifications')))) as fr21_security;

select jsonb_pretty(jsonb_build_object('triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',p.proname,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where not t.tgisinternal and n.nspname='public' and c.relname in ('users','riders','orders','rider_assignments','vendor_orders','vendors','notifications')),'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definer',p.prosecdef,'config',p.proconfig)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f'),'verification',(select jsonb_agg(to_jsonb(v)) from (select u.role,u.verification_status,count(*) as riders from public.riders r join public.users u on u.id=r.userid group by u.role,u.verification_status) v))) as fr21_dependencies;
